import { getConfig } from "../constants/config";
import { formatUnits } from "viem";
import { getTotalAmountIn } from "./getTotalAmountIn";
import { getTokenIn } from "./getTokenIn";
import { getTokenOut } from "./getTokenOut";
import { getSwapTypes } from "./getSwapTypes";

export const getRouteDetails = (route) => {
  try {
    const { tokens } = getConfig();
    // Validate required parameters
    if (!route || !Array.isArray(route) || route?.length === 0) {
      console.error("Invalid or missing `route`: Must be an array.");
      return {
        totalOut: undefined,
        pathPercentages: undefined,
        pathCount: undefined,
        totalOutFormatted: undefined,
        amountIn: undefined,
        amountInFormatted: undefined,
        swapTypes: undefined,
        tokenIn: undefined,
        tokenOut: undefined,
        tokenInData: undefined,
        tokenOutData: undefined,
        route: route,
      };
    }

    const totalAmountIn = getTotalAmountIn(route);
    const amountIn = totalAmountIn.amountIn;
    const amountInFormatted = totalAmountIn.amountInFormatted;
    const tokenIn = getTokenIn(route);
    const tokenOut = getTokenOut(route);
    const swapTypes = getSwapTypes(route);
    // Retrieve token decimals
    const tokenInData = tokens[tokenIn];
    const tokenOutData = tokens[tokenOut];

    if (!tokenInData || !tokenInData.attributes?.decimals) {
      throw new Error(
        `Token ${tokenIn} data or decimals missing. This might mean token is not listed on Symphony.`
      );
    }
    if (!tokenOutData || !tokenOutData.attributes?.decimals) {
      throw new Error(
        `Token ${tokenOut} data or decimals missing. This might mean token is not listed on Symphony.`
      );
    }

    const tokenInDecimals = tokenInData.attributes.decimals;
    const tokenOutDecimals = tokenOutData.attributes.decimals;

    // Initialize outputs
    let totalOut = 0n;

    const pathPercentages = [];
    const pathCount = route.length;

    for (let i = 0; i < pathCount; i++) {
      const path = route[i];

      // Validate path structure
      if (!Array.isArray(path) || path.length === 0) {
        throw new Error(
          `Invalid path at index ${i}: Must be a non-empty array.`
        );
      }

      const pathOut = BigInt(path[path.length - 1]?.amountOutMin || 0);
      const pathIn = BigInt(path[0]?.amountIn || 0);

      totalOut += pathOut;

      // Calculate path percentage
      const pathInFormatted = Number(formatUnits(pathIn, tokenInDecimals));

      const pathPercent = Math.round(
        (pathInFormatted / Number(amountInFormatted)) * 100
      );

      pathPercentages.push(pathPercent);
    }

    // Format total output
    const totalOutFormatted = formatUnits(totalOut, tokenOutDecimals);
    return {
      totalOut,
      pathPercentages,
      pathCount,
      totalOutFormatted,
      amountIn,
      amountInFormatted,
      swapTypes,
      tokenIn,
      tokenOut,
      tokenInData,
      tokenOutData,
      route,
    };
  } catch (error) {
    // Catch and rethrow the error for logging/debugging
    console.error("Error in getRouteDetails:", error.message);
    throw error;
  }
};
