import { getConfig } from "../constants/config";
import { getTotalAmountOut } from "./getTotalAmountOut";
import { parseUnits, formatUnits } from "viem";
import { symphonyAddress, symphonyAbi } from "../../common/constants/contract";

/**
 * Calculates the minimum output amount for a swap considering slippage tolerance.
 * Supports various input formats and slippage representations.
 *
 * @param {Object} params - Calculation parameters
 * @param {(string|bigint|Array)} params.variable - Amount or route to calculate minimum for
 *   - If string: Amount in raw or formatted units
 *   - If bigint: Amount in raw units
 *   - If Array: Route from getRoute
 * @param {(string|number)} [params.slippageAmount=config.slippage] - Slippage tolerance
 *   - If isBps=false: Percentage (e.g., "0.5" for 0.5%)
 *   - If isBps=true: Basis points (e.g., 5000 for 0.5%)
 * @param {Object} [params.options] - Calculation options
 * @param {boolean} [params.options.isRaw=true] - If true, amounts are in raw units
 * @param {boolean} [params.options.isBps=false] - If true, slippage is in basis points
 * @param {number} [params.options.outTokenDecimals] - Decimals for output token
 *   Required when using formatted amounts
 *
 * @returns {bigint} Minimum output amount in raw units
 *
 * @throws {Error} If variable or slippageAmount is missing/invalid
 * @throws {Error} If slippage calculation fails
 *
 * @example
 * // Example 1: Calculate min output for a route with 0.5% slippage
 * const minOut = calculateAmountOutMin({
 *   variable: route,
 *   slippageAmount: "0.5"
 * });
 *
 * @example
 * // Example 2: Calculate with basis points slippage
 * const minOut = calculateAmountOutMin({
 *   variable: "1000000000000000000", // 1 token in wei
 *   slippageAmount: 50, // 0.5% in bps
 *   options: {
 *     isRaw: true,
 *     isBps: true
 *   }
 * });
 *
 * @example
 * // Example 3: Calculate with formatted amount
 * const minOut = calculateAmountOutMin({
 *   variable: "1.0",
 *   slippageAmount: "0.5",
 *   options: {
 *     isRaw: false,
 *     outTokenDecimals: 18
 *   }
 * });
 *
 * @note
 * - Returns original amount if slippage is 0
 * - Returns 0 if slippage >= 100% (or >= 10000 bps)
 * - Warns if slippage is unusually high
 */
export const calculateAmountOutMin = async ({
  variable, // route or amount
  slippageAmount = getConfig().slippage,
  options = {
    isRaw: true,
    isBps: false,
    outTokenDecimals: undefined,
  },
}) => {
  const publicClient = getConfig().publicClient;
  const feeParams = getConfig().feeParams;
  let amountOut = 0n;
  let slippage = 0;
  if (
    !variable ||
    !slippageAmount ||
    (Array.isArray(variable) && variable?.length == 0)
  ) {
    throw new Error("Invalid or missing `variable` or `slippageAmount` arg.");
  }

  //If variable is Route
  if (Array.isArray(variable) && variable.length != 0)
    amountOut = getTotalAmountOut(variable).amountOut;

  //If variable is raw string
  if (typeof variable == "string" && options.isRaw)
    amountOut = BigInt(variable);

  // If variable is formatted string
  if (typeof variable == "string" && !options.isRaw)
    amountOut = parseUnits(variable, options.outTokenDecimals);

  // If variable is bigint
  if (typeof variable == "bigint") amountOut = variable;

  // if slippage is formatted string or float/number
  if (
    (typeof slippageAmount == "string" || typeof slippageAmount == "number") &&
    !options.isBps
  )
    slippage = slippageAmount.toString();
  // If slippage is bps units
  if (options.isBps) slippage = (Number(slippageAmount) / 10000).toString();

  if (Number(slippageAmount) == 0) {
    if (options.isRaw) return amountOut;
    if (!options.isRaw) return formatUnits(amountOut, options.outTokenDecimals);
    console.error(
      "Slippage is set to 0. Please set slippage to a non-zero value if not intended."
    );
  }

  if (
    (Number(slippageAmount) >= 100 && !options.isBps) ||
    (Number(slippageAmount) >= 1000000 && options.isBps)
  ) {
    console.error(
      "Slippage is set to 100% or higher. Please set slippage to a lower value if not intended."
    );
    return 0n;
  }

  if (!slippage || !amountOut) {
    if (!slippage) throw new Error("Error setting slippage!");
    if (!amountOut)
      throw new Error(
        "Error setting slippage: No amount out provided! This might mean swap value is too low. (Return token amount is 0)"
      );
  }
  const integerPart = slippage.split(".")[0] || "0";
  const fractionalPart = slippage.split(".")[1] || "";

  const numerator = (
    integerPart.toString() + fractionalPart.toString()
  ).replace(/^0+|0+$/g, "");

  const denominatorExp = fractionalPart.length + 2;

  let amountOutMin =
    amountOut - (amountOut * BigInt(numerator)) / BigInt(10 ** denominatorExp);

  //DEDUCT CUSTOM FEE AMOUNT IF ANY
  if (
    feeParams.feeAddress !== "0x0000000000000000000000000000000000000000" &&
    Number(feeParams.paramFee) &&
    Number(feeParams.paramFee) !== 0
  ) {
    const feeAmount = (amountOutMin * BigInt(feeParams.paramFee)) / 1000n;
    amountOutMin = amountOutMin - feeAmount;
  }
  //DEDUCT PLATFORM FEE IF THERES NOT A CUSTOM FEE
  if (feeParams.feeAddress === "0x0000000000000000000000000000000000000000") {
    const platformFee = await publicClient.readContract({
      address: symphonyAddress,
      abi: symphonyAbi,
      functionName: "feePercentage",
    });

    const feeAmount = (amountOutMin * platformFee) / 1000n;

    amountOutMin = amountOutMin - feeAmount;
  }

  if (amountOutMin < 0n) {
    console.error(
      "Error setting slippage: Minimum amount is negative. This might mean slippage value or custom fee is higher than 100%. Minimum amount set to `0`."
    );
    return 0n;
  }

  return amountOutMin;
};
