import { getRoute } from "../core/getRoute";
import { setConfig, getConfig } from "../constants/config";
import { Route } from "./route";

export class Symphony {
  constructor({ walletClient = undefined, options = {} } = {}) {
    this.walletClient = walletClient;
    setConfig(options);
  }

  connectWalletClient(walletClient) {
    this.walletClient = walletClient;
  }
  disconnectWalletClient() {
    this.walletClient = undefined;
  }
  async getRoute(tokenIn, tokenOut, amountIn, options = {}) {
    const defaultOptions = { isRaw: false };
    const mergedOptions = { ...defaultOptions, ...options };
    const routePayload = await getRoute(
      tokenIn,
      tokenOut,
      amountIn,
      mergedOptions
    );
   
    // Pass a getter function to the Route object
    return new Route(routePayload, () => this.walletClient, mergedOptions);
  }

  getTokenList() {
    const config = getConfig();
    return { ...config.tokens };
  }

  isTokenListed(tokenAddress) {
    if (typeof tokenAddress != "string" || !tokenAddress.startsWith("0x"))
      console.error(
        `Cannot verify token 'tokenAddress' parameter is not valid. tokenAddress: ${tokenAddress}`
      );
    const token = getConfig().tokens[tokenAddress?.toString()?.toLowerCase()];
    return !!token;
  }

  getConfig() {
    return getConfig();
  }

  setConfig(options) {
    setConfig(options);
  }
}
